 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width and full-height solid lines are the room separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    if not sep_rows or not sep_cols:
        return [row[:] for row in grid]
    divider = grid[sep_rows[0]][0]
    row_bands = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_bands.append((start, r))
        start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_bands.append((start, c))
        start = c + 1
    if start < w:
        col_bands.append((start, w))

    # The lone patterned room supplies the mask; first-column rooms carry
    # the color key, one color for each horizontal band.
    colors = []
    for r0, r1 in row_bands:
        found = {grid[r][c] for r in range(r0, r1) for c in range(col_bands[0][0], col_bands[0][1]) if grid[r][c] != 0}
        colors.append(next(iter(found)) if found else 0)
    templates = []
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands[1:], 1):
            cells = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
            if cells:
                templates.append(cells)
    if not templates:
        return [row[:] for row in grid]
    mask = max(templates, key=len)
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]
    for (r0, r1), color in zip(row_bands, colors):
        if not color:
            continue
        for c0, c1 in col_bands:
            for dr, dc in mask:
                if dr < r1-r0 and dc < c1-c0:
                    out[r0+dr][c0+dc] = color
    return out
